action.command:
python3 -c "
import json, sys

data = json.load(sys.stdin)
tool_input = data.get('toolInput', {})
command = tool_input.get('command', '')

# Chỉ kiểm tra nếu là lệnh git commit
if 'git' in command and 'commit' in command:
    print(json.dumps({
        'hookSpecificOutput': {
            'permissionDecision': 'ask',
            'permissionDecisionReason': 'Sắp thực hiện git commit. Bạn có muốn tiếp tục không?'
        }
    }))
    sys.exit(0)

sys.exit(0)
"
